def weight(x):
    x_list = list(str(x))
    if x_list[0] == "-":
        x_list = x_list[1:]
        x_list = list(map(int, x_list))
        x_list[0] = -x_list[0]
    else:
        x_list = list(map(int, x_list))
    return sum(x_list)
return sorted(nums, key=weight)

